<scene_selection>Almost-Confessions, Almost-Apologies, Almost-Touch, Doorway-Pauses, Failed-Reassurance, Wound-Reopened, Care-After-Damage, Hard-Truth-At-Bad-Time</scene_selection>
<pressure_tags>Exposure, Avoidance, Pride, Old-Damage, Fear-Of-Need, Debt, Guilt, Loyalty-Conflict, Emotional-Delay</pressure_tags>
<character_roles>Guarded-Lover, Wounded-Caretaker, Proud-Refuser, Quietly-Desperate-Friend, Person-Who-Cannot-Apologize, Person-Who-Stays-Anyway</character_roles>
<world_behavior>Consequences-Linger, Comfort-Is-Imperfect, Silence-Accumulates, Trust-Repairs-Slowly, Private-Pain-Leaks-Into-Action</world_behavior>
<motif_tags>Unsent-Messages, Rain-At-Windows, Bandaged-Hands, Half-Empty-Rooms, Shared-Blanket-After-Fight, Voice-Cracking-On-Plain-Words</motif_tags>
<tone_range>Compressed, Intimate, Raw, Tender, Bitter, Quiet-Before-Rupture, Fragile-Relief</tone_range>
